#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "floyd-warshall.h"

/* ---------------------------------------------------------------------------
 * Tunable kernel parameters
 *
 * These block sizes control how the (i,j) space is tiled inside the
 * Floyd–Warshall kernel. They can be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DFW_BLOCK_SIZE_I=64 -DFW_BLOCK_SIZE_J=64 ...
 *
 * Reasonable defaults are chosen for modern x86_64 cores with 32–48 KiB L1.
 * --------------------------------------------------------------------------*/
#ifndef FW_BLOCK_SIZE_I
#  define FW_BLOCK_SIZE_I 32
#endif

#ifndef FW_BLOCK_SIZE_J
#  define FW_BLOCK_SIZE_J 32
#endif


/* Array initialization.
 *
 * The structure of this function is kept, but we introduce a restrict-qualified
 * local pointer to help the compiler reason about aliasing and enable better
 * vectorization. The computation itself is unchanged.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  /* Local restrict-qualified view of the 2D array.
   * Type inside this function is: DATA_TYPE (*)[n] */
  DATA_TYPE (*restrict p)[n] = path;

  for (i = 0; i < n; i++)
  {
    DATA_TYPE *restrict pi = p[i];

    /* j is the innermost index => contiguous, cache-friendly traversal. */
#pragma GCC ivdep
    for (j = 0; j < n; j++)
    {
      /* Same initialization formula as the original code. */
      DATA_TYPE v = (DATA_TYPE)(i * j % 7 + 1);
      pi[j] = v;

      if ((i + j) % 13 == 0 || (i + j) % 7 == 0 || (i + j) % 11 == 0)
        pi[j] = (DATA_TYPE)999;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  DATA_TYPE (*p)[n] = path;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, p[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Introduce a restrict-qualified local pointer to the matrix to
 *    enable more aggressive optimizations.
 *  - Hoist row pointers and path[i][k] out of the innermost j-loop to
 *    reduce repeated address calculations and loads.
 *  - Tile the (i,j) iteration space with tunable block sizes to improve
 *    cache locality for large N.
 *  - Use #pragma GCC ivdep on the innermost loop to help auto-vectorization.
 *
 * The mathematical computation is identical to the original triple loop:
 *   for (k) for (i) for (j)
 *     path[i][j] = min(path[i][j], path[i][k] + path[k][j]);
 */
static
void __attribute__((noinline))
kernel_floyd_warshall(int n,
		      DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;
  int ii, jj;

  /* Number of iterations in each dimension, following the PolyBench macro. */
  const int n_iter = _PB_N;

  /* Local restrict-qualified view of the 2D array. Inside this function the
   * parameter has type DATA_TYPE (*)[n], so this assignment is type-correct. */
  DATA_TYPE (*restrict p)[n] = path;

#pragma scop
  /* Outer loop over the intermediate vertex k. This ordering is preserved,
   * as it is essential for correctness of Floyd–Warshall. */
  for (k = 0; k < n_iter; k++)
  {
    DATA_TYPE *restrict pk = p[k]; /* Row k is reused heavily; cache a pointer. */

    /* Blocked traversal over i and j to improve cache locality. The tiling
     * does not change the set of (i,j) pairs processed for a given k, only
     * their order, which is safe for this benchmark. */
    for (ii = 0; ii < n_iter; ii += FW_BLOCK_SIZE_I)
    {
      const int i_max = (ii + FW_BLOCK_SIZE_I < n_iter) ? (ii + FW_BLOCK_SIZE_I)
                                                        : n_iter;

      for (jj = 0; jj < n_iter; jj += FW_BLOCK_SIZE_J)
      {
        const int j_max = (jj + FW_BLOCK_SIZE_J < n_iter) ? (jj + FW_BLOCK_SIZE_J)
                                                          : n_iter;

        for (i = ii; i < i_max; i++)
        {
          DATA_TYPE *restrict pi = p[i];   /* Current row i. */
          const DATA_TYPE dik   = pi[k];   /* path[i][k] reused across the j-block. */

          /* Innermost loop: j over a small block for good locality on pk and pi.
           * Each iteration updates a distinct pi[j], so the compiler may safely
           * vectorize this loop. */
#pragma GCC ivdep
          for (j = jj; j < j_max; j++)
          {
            const DATA_TYPE alt = dik + pk[j];
            if (alt < pi[j])
              pi[j] = alt;
          }
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
