 * These constants control the tile sizes used to block the i- and j-loops
 * in the Floyd–Warshall kernel. They can be tuned at compile time to better
 * match a particular cache hierarchy, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DFW_BLOCK_SIZE_I=64 -DFW_BLOCK_SIZE_J=64 ...
 *
 * The transformation preserves the original semantics for all inputs.  The
 * blocking reorders iterations, but it maintains the monotonic increasing
 * order of both i and j for every fixed (k, j) and (k, i) respectively,
 * which is required to respect the original read-after-write and
 * write-after-read dependencies on path[i][k] and path[k][j].
 * ---------------------------------------------------------------------- */
#ifndef FW_BLOCK_SIZE_I
# define FW_BLOCK_SIZE_I 32
#endif

#ifndef FW_BLOCK_SIZE_J
# define FW_BLOCK_SIZE_J 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      path[i][j] = i*j%7+1;
      if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
         path[i][j] = 999;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   --------------
   1. Use a local 'restrict'-qualified pointer to the path matrix to give the
      compiler stronger aliasing information and help vectorization.
   2. Replace the ternary operator with an explicit if-statement; this tends
      to produce better vectorizable inner loops.
   3. Apply cache blocking to the (i,j) loops:

        Original order: for k in [0,N)
                          for i in [0,N)
                            for j in [0,N)

        New order:      for k in [0,N)
                          for ii in tiles of i
                            for jj in tiles of j
                              for i in [ii, min(ii+BS_I,N))
                                for j in [jj, min(jj+BS_J,N))

      The blocking improves spatial and temporal locality of accesses to
      path[i][*] and path[*][j] without violating the data dependencies:

        - For fixed (k, i), j still increases monotonically across all tiles,
          so the relative order of all (k, i, j) iterations is preserved.
        - For fixed (k, j), i still increases monotonically, preserving the
          relative order of all (k, i, j) iterations in that column.

      Thus all read-after-write, write-after-read, and write-after-write
      dependencies in the original triple-nested loop are preserved exactly.
*/
static
void kernel_floyd_warshall [[gnu::flatten, gnu::noinline]] (int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;
  int ii, jj;

  /* Local alias with 'restrict' to help the compiler optimize memory access.
     The layout is still a contiguous row-major n x n matrix. */
  DATA_TYPE (*restrict path_)[n] = path;

  const int n_ = _PB_N;

#pragma scop
  for (k = 0; k < n_; k++)
    {
      /* For better locality, operate on tiles of the (i,j) space. */
      for (ii = 0; ii < n_; ii += FW_BLOCK_SIZE_I)
      {
        int i_end = ii + FW_BLOCK_SIZE_I;
        if (i_end > n_)
          i_end = n_;

        for (jj = 0; jj < n_; jj += FW_BLOCK_SIZE_J)
        {
          int j_end = jj + FW_BLOCK_SIZE_J;
          if (j_end > n_)
            j_end = n_;

          for (i = ii; i < i_end; i++)
          {
            /* Row pointer for fast linear access in j. */
            DATA_TYPE *restrict row_i = path_[i];

            for (j = jj; j < j_end; j++)
            {
              /* Compute candidate path via intermediate vertex k. */
              DATA_TYPE alt = row_i[k] + path_[k][j];

              /* Update with minimum, using an explicit branch instead of ?: */
              if (row_i[j] > alt)
                row_i[j] = alt;
            }
          }
        }
      }
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
