 * Tunable blocking factors for the Floyd–Warshall kernel.
 *
 * These control the tile sizes in the i and j dimensions for better
 * cache locality. They can be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DFLOYD_WARSHALL_BLOCK_I=64 -DFLOYD_WARSHALL_BLOCK_J=64 ...
 *
 * When the problem size N is small, the code automatically caps the
 * block sizes by the actual loop bound, so any positive values are safe.
 * Setting one of them >= N (or leaving defaults) effectively disables
 * blocking along that dimension.
 * ------------------------------------------------------------------ */
#ifndef FLOYD_WARSHALL_BLOCK_I
#  define FLOYD_WARSHALL_BLOCK_I 32
#endif

#ifndef FLOYD_WARSHALL_BLOCK_J
#  define FLOYD_WARSHALL_BLOCK_J 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      path[i][j] = i*j%7+1;
      if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
         path[i][j] = 999;
    }
}


