      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* Local alias with explicit restrict for better alias analysis.
     The original POLYBENCH_2D type is a VLA of size [n][n], so this
     pointer type matches it exactly. We use only 'path_' below to
     honor the restrict contract. */
  DATA_TYPE (*restrict path_)[n] = path;

  /* Use the PolyBench-provided loop bound. This is typically equal to n,
     but using the macro allows PolyBench to internally scale problem
     sizes if desired. */
  const int n_iter = _PB_N;

  /* Effective block sizes (capped by loop bound and forced positive).
     This makes the blocking tunable while remaining safe for all n. */
  const int bi = (FLOYD_WARSHALL_BLOCK_I > 0 && FLOYD_WARSHALL_BLOCK_I < n_iter)
                   ? FLOYD_WARSHALL_BLOCK_I
                   : n_iter;
  const int bj = (FLOYD_WARSHALL_BLOCK_J > 0 && FLOYD_WARSHALL_BLOCK_J < n_iter)
                   ? FLOYD_WARSHALL_BLOCK_J
                   : n_iter;

#pragma scop
