     Floyd–Warshall DP. We keep k outermost to preserve the dynamic
     programming semantics. */
  for (k = 0; k < n_iter; k++)
    {
      /* Row k is read-only within this k-iteration (except when i == k;
         see inner loops). Hoist its base pointer once per k to improve
         cache locality and reduce index arithmetic. */
      const DATA_TYPE *row_k = path_[k];

      /* 2D blocking over (i, j) to improve cache locality. For a fixed k,
         all (i, j) updates are independent, so we are free to reorder
         them as long as we preserve:
           - increasing j for each fixed i, and
           - increasing i for each fixed j.
         The (ii, jj) tiling keeps both properties, so semantics match
         the original triple-nested loops exactly. */
      for (int ii = 0; ii < n_iter; ii += bi)
      {
        const int i_end = (ii + bi < n_iter) ? (ii + bi) : n_iter;

        for (int jj = 0; jj < n_iter; jj += bj)
        {
          const int j_end = (jj + bj < n_iter) ? (jj + bj) : n_iter;

          /* Loop over the rows in this i-tile. */
          for (i = ii; i < i_end; i++)
          {
            DATA_TYPE *row_i = path_[i];

            /* path[i][k] is reused for all j in this row and k,
               so hoist it into a scalar to avoid redundant loads. */
            const DATA_TYPE ik = row_i[k];

            /* Inner-most loop over contiguous j. Both row_i[j] and
               row_k[j] are contiguous in memory, so this loop is
               vectorization friendly.

               ivdep tells GCC that there are no loop-carried
               dependencies along j, which is true here: each (i,j)
               element is written exactly once for a given k and is
               never read again in this k-iteration. */
#pragma GCC ivdep
            for (j = jj; j < j_end; j++)
            {
