              const DATA_TYPE direct  = row_i[j];

              /* Branchless min: keeps the same semantics as the original
                 ternary expression, but is typically compiled to a
                 compare-and-select (or vector min) which is efficient. */
              row_i[j] = (direct <= via_k) ? direct : via_k;
            }
          }
        }
      }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
