#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "floyd-warshall.h"

/* --------------------------------------------------------------------
 * Tunable blocking parameters
 *
 * These constants control the cache blocking of the main kernel.
 * They can be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DFW_BLOCK_I=64 -DFW_BLOCK_J=64 ...
 *
 * Choose them so that FW_BLOCK_I * FW_BLOCK_J * sizeof(DATA_TYPE)
 * fits comfortably into L1/L2 cache.
 * ------------------------------------------------------------------ */
#ifndef FW_BLOCK_I
# define FW_BLOCK_I 32
#endif

#ifndef FW_BLOCK_J
# define FW_BLOCK_J 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      path[i][j] = i*j%7+1;
      if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
         path[i][j] = 999;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use an explicit pointer-to-row with 'restrict' to help the
     compiler understand the 2D array layout and avoid repeated
     address recomputation.
   - Cache-block the iteration space in i and j to improve data
     locality for large matrices.
   - Keep the innermost loop over j so that each row is traversed
     contiguously in memory, which is cache- and SIMD-friendly.
   - Preserve the exact dependency structure of the original
     algorithm for all possible inputs (no assumptions about edge
     weights, including sign), so the numerical results remain
     identical to the original triple loop.
*/
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* Cast to a pointer-to-row type with 'restrict' to tell the compiler
     that no other pointer aliases this matrix.  This matches how
     PolyBench allocates the array and reduces index arithmetic. */
  DATA_TYPE (* restrict path_)[n] = path;

  /* PolyBench provides _PB_N as a possibly adjusted loop bound. */
  const int n_pb = _PB_N;

#pragma scop
  for (k = 0; k < n_pb; k++)
    {
      /* Pointer to the k-th row. This row is reused heavily across
         all i and j for the current k, so keeping a dedicated pointer
         improves locality and reduces address computation. */
      DATA_TYPE * restrict row_k = path_[k];

      /* 2D blocking in i and j.  The loop nest order:
           for k
             for ii
               for jj
                 for i in tile(ii)
                   for j in tile(jj)
         preserves:
           - increasing j for each fixed i
           - increasing i for each fixed j
         which is sufficient to maintain all true data dependencies
         of the original k-i-j nest, even for arbitrary (including
         negative) weights. */
      for (int ii = 0; ii < n_pb; ii += FW_BLOCK_I)
        {
          const int i_end = (ii + FW_BLOCK_I < n_pb) ? (ii + FW_BLOCK_I) : n_pb;

          for (int jj = 0; jj < n_pb; jj += FW_BLOCK_J)
            {
              const int j_end = (jj + FW_BLOCK_J < n_pb) ? (jj + FW_BLOCK_J) : n_pb;

              for (i = ii; i < i_end; i++)
                {
                  DATA_TYPE * restrict row_i = path_[i];

                  /* Inner-most j loop walks contiguous elements of row_i.
                     We *do not* hoist row_i[k] out of this loop: in the
                     original algorithm path[i][k] may change at j == k
                     and must be seen updated for j > k.  Reloading
                     row_i[k] each iteration preserves that dependency. */
                  for (j = jj; j < j_end; j++)
                    {
                      DATA_TYPE via = row_i[k] + row_k[j];
                      if (via < row_i[j])
                        row_i[j] = via;
                    }
                }
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
